// Tisple ][ for VS Code: errors from `tisple check`, formatting through `tisple fmt`, and a
// command that builds the open program and runs it in the built-in Apple IIe. Highlighting
// is the TextMate grammar in syntaxes/, generated by `tisple gen-editors editors`.

const vscode = require("vscode");
const cp = require("child_process");
const fs = require("fs");
const os = require("os");
const path = require("path");

let diagnostics = null;

// the tisple binary: the setting, else build-debug/tisple in a folder above the file, else PATH
function tisplePath(fileName) {
    const configured = vscode.workspace.getConfiguration("tisple").get("path");
    if (configured) {
        return configured;
    }
    let dir = path.dirname(fileName);
    for (let i = 0; i < 8; i++) {
        const candidate = path.join(dir, "build-debug", "tisple");
        if (fs.existsSync(candidate)) {
            return candidate;
        }
        const parent = path.dirname(dir);
        if (parent === dir) {
            break;
        }
        dir = parent;
    }
    return "tisple";
}

// "file:line:col: message" lines from check, fmt and the reader
function parseErrors(output, fileName) {
    const byFile = new Map();
    for (const line of output.split("\n")) {
        const m = /^(.*?):(\d+):(\d+): (.*)$/.exec(line);
        if (!m) {
            continue;
        }
        const file = path.resolve(path.dirname(fileName), m[1]);
        const at = new vscode.Position(Number(m[2]) - 1, Number(m[3]) - 1);
        const range = new vscode.Range(at, at.translate(0, 1));
        const severity = m[4].startsWith("note:")
            ? vscode.DiagnosticSeverity.Information
            : vscode.DiagnosticSeverity.Error;
        const d = new vscode.Diagnostic(range, m[4], severity);
        d.source = "tisple";
        if (!byFile.has(file)) {
            byFile.set(file, []);
        }
        byFile.get(file).push(d);
    }
    return byFile;
}

function checkDocument(doc) {
    if (doc.languageId !== "tisple" || doc.uri.scheme !== "file") {
        return;
    }
    const tool = tisplePath(doc.fileName);
    cp.execFile(tool, ["check", doc.fileName], { cwd: path.dirname(doc.fileName) },
        (error, stdout, stderr) => {
            if (error && error.code === "ENOENT") {
                vscode.window.showWarningMessage(
                    "Tisple: no tisple binary found; set tisple.path or build the repo.");
                return;
            }
            diagnostics.clear();
            const byFile = parseErrors(stdout + stderr, doc.fileName);
            if (!byFile.has(doc.fileName)) {
                diagnostics.set(doc.uri, []);
            }
            for (const [file, list] of byFile) {
                diagnostics.set(vscode.Uri.file(file), list);
            }
        });
}

// formats a copy in a temp file, so an unsaved buffer formats as it is
function formatDocument(doc) {
    const tool = tisplePath(doc.fileName);
    const tmp = path.join(os.tmpdir(), `tisple-fmt-${process.pid}.tsp`);
    fs.writeFileSync(tmp, doc.getText());
    try {
        const out = cp.execFileSync(tool, ["fmt", tmp], { encoding: "utf8" });
        if (out === doc.getText()) {
            return [];
        }
        const all = new vscode.Range(doc.positionAt(0), doc.positionAt(doc.getText().length));
        return [vscode.TextEdit.replace(all, out)];
    } catch (e) {
        // a reader error: leave the text alone; check shows the error
        return [];
    } finally {
        fs.rmSync(tmp, { force: true });
    }
}

function runOnApple2() {
    const editor = vscode.window.activeTextEditor;
    if (!editor || editor.document.languageId !== "tisple") {
        vscode.window.showInformationMessage("Tisple: open a .tsp file first.");
        return;
    }
    const doc = editor.document;
    doc.save().then(() => {
        const tool = tisplePath(doc.fileName);
        const q = (s) => `'${s.replace(/'/g, "'\\''")}'`;
        const terminal = vscode.window.terminals.find((t) => t.name === "Tisple ][") ||
            vscode.window.createTerminal("Tisple ][");
        terminal.show(true);
        terminal.sendText(`${q(tool)} run ${q(doc.fileName)}`);
    });
}

function activate(context) {
    diagnostics = vscode.languages.createDiagnosticCollection("tisple");
    context.subscriptions.push(diagnostics);
    context.subscriptions.push(vscode.workspace.onDidSaveTextDocument(checkDocument));
    context.subscriptions.push(vscode.workspace.onDidOpenTextDocument(checkDocument));
    context.subscriptions.push(vscode.languages.registerDocumentFormattingEditProvider(
        "tisple", { provideDocumentFormattingEdits: formatDocument }));
    context.subscriptions.push(vscode.commands.registerCommand("tisple.run", runOnApple2));
    vscode.workspace.textDocuments.forEach(checkDocument);
}

function deactivate() {}

module.exports = { activate, deactivate };
